-- Science-Nin's "S.N.B Upgrades" (the Scientific Ninja Beast's own Minor/
-- Refined/Greater/Superior/Supreme/Mastercraft upgrade tiers) was ingested
-- as a phantom 11th subclass of the Scientific Inquiry group instead of a
-- class_options catalog scoped to S.N.B Specialist -- the pattern every
-- other subclass's own analogous upgrade catalog correctly follows (e.g.
-- Shinobi-Ware's "Shinobi-Ware Upgrades" tiers ARE class_options rows under
-- subclass_slug = shinobi-ware, not a second subclass named "Shinobi-Ware
-- Upgrades"). Root cause: the PDF outline bookmarks S.N.B Upgrades as a
-- sibling of S.N.B Specialist inside the Scientific Inquiry group, and
-- internal/parse/subclasses.go's isSubclass heuristic (>=50% of a node's
-- children read as level-gated prose) misclassified it as a real subclass,
-- because several of its bundled upgrade entries mention a level number in
-- their own scaling text ("this bonus increases to +2 at 9th level") even
-- though the upgrade itself has no level gate of its own. Net effect before
-- this fix: loadSubclassOptions (cmd/n5e/characters.go) would surface
-- "S.N.B Upgrades" as a pickable 3rd-level Scientific Inquiry alongside the
-- 10 real ones, and the whole upgrade catalog was invisible to every
-- class_options-driven code path.
--
-- internal/parse/subclasses.go now special-cases this one bookmark node on
-- any future re-ingest, routing it into an option list attributed to S.N.B
-- Specialist (the subclass printed immediately before it) instead of
-- through isSubclass's heuristic. This migration repairs an already-shipped
-- install: the 6 subclass_features rows under the phantom
-- .../s-n-b-upgrades subclass are re-inserted as class_options rows under
-- S.N.B Specialist, then the phantom rows and the phantom subclass itself
-- are deleted. No character has ever picked this phantom subclass (verified
-- against characters.db before writing this migration), so no character
-- data needs repair.
--
-- Every INSERT below is guarded by "WHERE EXISTS (... the phantom subclass
-- row ...)" so this migration is a true no-op on a database that never had
-- the bug in the first place -- a fresh install (whose first ingest already
-- runs through the fixed parser above) or one that already applied this
-- migration once. Without the guard, re-running migrations against an empty
-- schema-only database (as internal/store's own tests do) would try to
-- insert class_options rows referencing a class_slug/subclass_slug that
-- doesn't exist yet and fail its FOREIGN KEY constraint.



INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/minor', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Minor', NULL, 'ARMORED EXTERIOR Cost: 2 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You add much needed reinforcement to your Scientific Ninja Beast. Your S.N.B’s AC calculation now begins at 12, this increase to 13 at 9th level and 14 at 17th level. CHAKRA CANNON Cost: 2 Creation Points Drain: 5 CCD Chakra You modify your Scientific Ninja Beast with the ability to fire raw chakra from its maw. Your S.N.B can spend the CCD Drain to make a ranged attack using its bite attack bonus against a target within 60 feet dealing Force damage equal to its bite damage. IMPROVED ACCURACY Cost: 2 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You upgrade your Scientific Ninja Beast to hit its targets better. Your S.N.B gains a +1 to attack rolls. This bonus increases to a +2 at 9th level and a +3 at 17th level. KUNAI/SHURIKEN LAUNCHER Cost: 2 Creation Points Drain: 5 CCD Chakra You install a mechanism in your Scientific Ninja Beast that allows it to launch a stack of kunai or shuriken over a large area. When you complete a rest, you can put any number of kunai/shuriken stacks into your S.N.B, your S.N.B can hold a number of kunai/shuriken stacks equal to your intelligence modifier. As an action, your S.N.B can the CCD Drain to use any amount of kunai/shuriken stacks to target a 30-foot area within 60 feet, each creature in the area must make a Dexterity saving throw, taking 4d4 piercing/slashing damage for each stack of ammunition consumed on a failed or half as much on a successful save. PISTON LEGS Cost: 2 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You outfit your Scientific Ninja Beast with extremely powerful legs increasing its speed and jump distance. Your S.N.B’s movement speed becomes 60 fee, its jump distance is tripled and your S.N.B can take the dash action as a Bonus Action.', 0, 'book/class-compendium', '3.12', 212, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');

INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/refined', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Refined', NULL, 'ASSISTANCE PROTOCOL Cost: 4 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You have upgraded your Scientific Ninja Beast’s protocol allowing it to better assist you and your allies. Your S.N.B can use the help action from 30 feet. When you reach level 14th your S.N.B can use the help action as a bonus action. CHAKRA DETECTION RADAR Cost: 4 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You install chakra detection hardware into your Scientific Ninja Beast. Your S.N.B gains 30 feet of Chakra Sight. If it detects a creature using this chakra sight you are immediately notified. DANGER RADAR Cost: 4 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You modify your Scientific Ninja Beast with software able to detect when an enemy is approaching. Your S.N.B can detect any hostile creature within 30 feet of it. If a creature is hidden this does not mean that it knows exactly where it is just that it is nearby. ENHANCED SIZE Cost: 4 Creation Points Drain: 5 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You decide your S.N.B is due for an upgrade and reconstruct it to increase its size. Your Scientific Ninja Beast size increases to Large. KUNAI-PROOF ARMOR Prerequisite: Armored Exterior Cost: 4 Creation Points Drain: 5 CCD Chakra You enhance your S.N.B’s armor even further, choose between Bludgeoning, Piercing or Slashing damage, your S.N.B gains resistance to the chosen damage type, it gains another at 9th level and the final at 14th level.', 1, 'book/class-compendium', '3.12', 212, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');

INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/greater', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Greater', NULL, 'INTEGRATED POISON COMPARTMENT Cost: 8 Creation Points Drain: 10 CCD Chakra You install a system for administrating poison into your Scientific Ninja Beast, you can use a bonus action to store a poison in your possession into your S.N.B. When your S.N.B makes a bite attack you can the CCD Drain to choose for it to administer the poison. When administered this way the Save DC of the poison increases by +1. This bonus increases to +2 at 9th level and +3 at 17th Level. REGENERATING CHAKRA SHIELD Cost: 8 Creation Points Drain: 10 CCD Chakra You install a small shield generator that runs on chakra into your Scientific Ninja Beast. At the beginning of each turn your S.N.B may spend the CCD Drain to gain a number of temporary hit points equal to your Science-Nin level. STURDY Cost: 8 Creation Points Drain: 10 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You modify your Scientific Ninja Beast’s chassis to resist more damage. Your S.N.B’s hit points increase by an amount equal to 5 times your Science-Nin level, each Science-Nin level thereafter your S.N.B gains an additional 5 hit points. OVERCHARGED FANGS Cost: 8 Creation Points Drain: 10 CCD Chakra You modify your Scientific Ninja Beast to be able to send an electric current to its fangs. Your S.N.B can spend the CCD Drain as a bonus action to overcharge its fangs. While its fangs are overcharged, they deal an additional 1d8 Lightning damage. This increases to 2d8 at 13th level and 3d8 at 17th level. This overcharge lasts for 1 minute. Additionally, when you reach 13th level, when you hit a creature with a fang attack you can choose to apply a rank of Shocked instead of dealing damage. Your S.N.B can only benefit from one fang upgrade at a time. SERRATED FANGS Cost: 8 Creation Points Drain: 10 CCD Chakra You modify your Scientific Ninja Beast to be able to coat its fangs in spiraling wind. Your S.N.B can spend the CCD Drain as a bonus action to coat its fangs. While its fangs are coated, they deal an additional 1d8 Wind damage. This increases to 2d8 at 13th level and 3d8 at 17th level. This overcharge lasts for 1 minute. Additionally, when you reach 13th level, when you hit a creature with a fang attack you can choose to apply a rank of Bleed instead of dealing damage. Your S.N.B can only benefit from one fang upgrade at a time. SUPERCOOLED FANGS Cost: 8 Creation Points Drain: 10 CCD Chakra You modify your Scientific Ninja Beast to be able to chill its fangs to almost absolute zero. Your S.N.B can spend the CCD Drain as a bonus action to supercool its fangs. While its fangs are supercooled, they deal an additional 1d8 Cold damage. This increases to 2d8 at 13th level and 3d8 at 17th level. This overcharge lasts for 1 minute. Additionally, when you reach 13th level, when you hit a creature with a fang attack you can choose to apply a rank of Chilled instead of dealing damage. Your S.N.B can only benefit from one fang upgrade at a time. SUPERHEATED FANGS Cost: 8 Creation Points Drain: 10 CCD Chakra You modify your Scientific Ninja Beast to be able to heat its fangs to extreme temperatures. Your S.N.B can spend the CCD Drain as a bonus action to superheat its fangs. While its fangs are superheated, they deal an additional 1d8 Fire damage. This increases to 2d8 at 13th level and 3d8 at 17th level. This overcharge lasts for 1 minute. Additionally, when you reach 13th level, when you hit a creature with a fang attack you can choose to apply a rank of Burn instead of dealing damage. Your S.N.B can only benefit from one fang upgrade at a time.', 2, 'book/class-compendium', '2025-05-04 (auto, drive)', 213, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');

INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/superior', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Superior', NULL, 'SELF-DESTRUCT PROTOCOL Cost: 16 Creation Points Drain: 15 CCD Chakra You have installed a large bomb into your Scientific Ninja Beast. As an action your Scientific Ninja Beast can spend the CCD Drain to initiate a self-destruct sequence, at the end of 1 minute the S.N.B will explode. Each creature within a 60-foot radius of the S.N.B must make a dexterity saving throw, taking 20d8 + 1 for each point of chakra remaining in the C.C.D of the S.N.B or half as much on a successful save. At any point during the 1-minute countdown the S.N.B may use its action to immediately explode. You lose any creation points spent on S.N.B upgrades until you finish a full rest. Alternatively, when your S.N.B is reduced to 0 hit points you may use your reaction to trigger the explosion. INTEGRATED FLAMETHROWER Cost: 16 Creation Points Drain: 15 CCD Chakra You install a small but powerful flamethrower into your Scientific Ninja Beast. As an action your S.N.B may spend the CCD Drain to spew a flame in a 30-foot cone. Creatures caught in the cone must make a Dexterity saving throw taking Xd6 Fire damage on a failed save or half as much on a successful save where X equals your Science-Nin level (Rounded Down). FLIGHT APPARATUS Cost: 16 Creation Points Drain: 15 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You upgrade your Scientific Ninja Beast with some form of flying ability whether that be mechanical wings or jets in its feet. Your S.N.B gains a flying speed equal to its movement speed.', 3, 'book/class-compendium', '2025-05-04 (auto, drive)', 213, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');

INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/supreme', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Supreme', NULL, 'DISPLACEMENT HOLOGRAM Cost: 24 Creation Points Drain: 20 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You install a holographic projector into your Scientific Ninja Beast making it seem to be standing slightly further than it actually is. Attack rolls against your S.N.B are made at disadvantage, if it is hit by an attack, it doesn’t gain the benefit of this upgrade until the start of its next turn. This upgrade also doesn’t function if your S.N.B is incapacitated. DEFIBRILLATOR PAWS Cost: 24 Creation Points Drain: 20 CCD Chakra You add a protocol to your Scientific Ninja Beast directing it to assist you when your life is in danger by jumpstarting your heart. When you fall unconscious, your S.N.B can use your reaction and spend the CCD Drain to move its full movement towards you and attempt to resuscitate you. You regain 1 temporary hit point and will fall unconscious at the end of your next turn unless you are healed in some way.', 4, 'book/class-compendium', '3.12', 214, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');

INSERT INTO class_options (slug, class_slug, subclass_slug, list_name, name, prerequisites, description, sort_order, source_book, source_version, source_page, detection_status)
SELECT 'class/science-nin/option/s-n-b-upgrades/mastercraft', 'class/science-nin', 'class/science-nin/group/scientific-inquiry/s-n-b-specialist', 'S.N.B Upgrades', 'Mastercraft', NULL, 'GIANT SIZE Prerequisite: Enhanced Size Cost: 32 Creation Points Drain: 30 CCD Chakra Increase the cost of activating your S.N.B by the CCD Drain of this Upgrade. You have reconstructed your Scientific Ninja Beast, greatly increasing its size. Your S.N.B’s size becomes huge, and it deals an additional die of damage with its bite attack.', 5, 'book/class-compendium', '3.12', 214, 'auto'
WHERE EXISTS (SELECT 1 FROM subclasses WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades');


-- Remove the phantom subclass_features rows and the phantom subclass row
-- itself now that their content lives in class_options above (no-op if
-- neither exists).
DELETE FROM subclass_features
WHERE subclass_slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades';

DELETE FROM subclasses
WHERE slug = 'class/science-nin/group/scientific-inquiry/s-n-b-upgrades';
